#!/usr/bin/env node
// Bundle the kit plus a plugin's source into that plugin's desktop/plugin.js.
//
//   node scripts/build.mjs <plugin-dir> [<plugin-dir> ...] [--check]
//
// Entry:  <plugin-dir>/desktop/src/plugin.js   (imports the kit as 'hermes-ui-kit')
// Output: <plugin-dir>/desktop/plugin.js       (one ES module; only the SDK and React stay external)
//
// After writing, the output is checked against the catalog's desktop rules
// (plugin-catalog/README.md rule 8): imports only from '@hermes/plugin-sdk', 'react' and
// 'react/jsx-runtime', no eval or new Function, no dynamic import, no prototype patching,
// no script injection, no innerHTML. --check builds to memory and compares with the file
// on disk, failing if the committed bundle is out of date.
//
// It also copies the harness SDK stand-in (harness/kit-sdk-stub.js and .css) into
// <plugin-dir>/harness/ when that folder exists, so headless renders know the kit's
// SDK components.

import { copyFileSync, existsSync, readFileSync, realpathSync, writeFileSync } from 'node:fs'
import { dirname, join, relative, resolve, sep } from 'node:path'
import { fileURLToPath } from 'node:url'
import { createRequire } from 'node:module'

const KIT = realpathSync(resolve(dirname(fileURLToPath(import.meta.url)), '..')) // real path: /var and /private/var are one place
const require = createRequire(join(KIT, 'package.json'))
let esbuild
try {
  esbuild = require('esbuild')
} catch (e) {
  console.error('esbuild is missing. Run `npm ci` inside vendor/hermes-ui-kit (it installs the exact version in package-lock.json), then build again.')
  process.exit(2)
}

export const ALLOWED = ['@hermes/plugin-sdk', 'react', 'react/jsx-runtime']
const BANNED = [
  [/(?<![\w$.])eval\(/, 'eval('],
  [/\bnew\s+Function\(/, 'new Function('],
  [/\bimport\(/, 'dynamic import()'],
  [/\b[A-Za-z_$][\w$]*\.prototype\.[\w$]+\s*=[^=]/, 'prototype patching'],
  [/createElement\(\s*['"]script['"]\s*\)|<script\b/, 'script injection'],
  [/\binnerHTML\b/, 'innerHTML'],
  [/\bdocument\.(?:querySelector(?:All)?|getElementsBy\w+|getElementById)\(\s*[`'"][^`'"]*\[data-(?:slot|tour|sidebar|testid)\b/, 'reaching into app markup'],
]

export function importsOf(code) {
  return [...code.matchAll(/^\s*import\s[\s\S]*?\sfrom\s*["']([^"']+)["']/gm)].map(m => m[1])
}

export function ruleProblems(code) {
  const problems = []
  for (const source of importsOf(code)) if (!ALLOWED.includes(source)) problems.push(`imports ${source}`)
  for (const [pattern, name] of BANNED) if (pattern.test(code)) problems.push(name)
  return problems
}

const kitAlias = {
  name: 'hermes-ui-kit',
  setup(build) {
    build.onResolve({ filter: /^hermes-ui-kit$/ }, () => ({ path: join(KIT, 'src', 'index.js') }))
  },
}

export async function bundle(dir) {
  const pluginDir = realpathSync(resolve(dir))
  const entry = join(pluginDir, 'desktop', 'src', 'plugin.js')
  if (!existsSync(entry)) throw new Error(`no source at ${entry}`)
  const kitVersion = JSON.parse(readFileSync(join(KIT, 'package.json'), 'utf8')).version
  const out = await esbuild.build({
    entryPoints: [entry],
    absWorkingDir: pluginDir, // path comments in the output read the same from any cwd
    bundle: true,
    write: false,
    format: 'esm',
    platform: 'browser',
    target: 'es2022',
    charset: 'utf8',
    legalComments: 'none',
    treeShaking: true,
    external: ALLOWED,
    plugins: [kitAlias],
    banner: { js: `// Generated by hermes-ui-kit ${kitVersion} from desktop/src/. Edit the source and rebuild:\n//   node vendor/hermes-ui-kit/scripts/build.mjs .\n` },
    logLevel: 'warning',
  })
  // esbuild labels each file with its path relative to the plugin folder. Name the kit's files the same way wherever
  // the kit sits, so the output depends on the files' contents and not on where they were checked out.
  const kitRel = relative(pluginDir, KIT).split(sep).join('/')
  const label = new RegExp(`^// ${kitRel.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}/`, 'gm')
  return out.outputFiles[0].text.replace(label, '// hermes-ui-kit/')
}

async function main() {
  const args = process.argv.slice(2)
  const check = args.includes('--check')
  const dirs = args.filter(a => !a.startsWith('--'))
  if (!dirs.length) {
    console.error('usage: node scripts/build.mjs <plugin-dir> [...] [--check]')
    process.exit(2)
  }
  let failed = false
  for (const raw of dirs) {
    const dir = resolve(raw)
    const target = join(dir, 'desktop', 'plugin.js')
    const code = await bundle(dir)
    const problems = ruleProblems(code)
    if (problems.length) {
      console.error(`${dir}: the bundle breaks the desktop rules: ${problems.join(', ')}`)
      failed = true
      continue
    }
    if (check) {
      const same = existsSync(target) && readFileSync(target, 'utf8') === code
      console.log(`${target}: ${same ? 'up to date' : 'OUT OF DATE'}`)
      if (!same) failed = true
      continue
    }
    writeFileSync(target, code)
    const harness = join(dir, 'harness')
    if (existsSync(harness)) {
      for (const f of ['kit-sdk-stub.js', 'kit-sdk-stub.css']) copyFileSync(join(KIT, 'harness', f), join(harness, f))
    }
    console.log(`${target}: ${(code.length / 1024).toFixed(1)} KB, imports ${[...new Set(importsOf(code))].join(', ')}`)
  }
  process.exit(failed ? 1 : 0)
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main()
